INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(122067, 'ruRU', '', 'Все эти бумаги. Как мы вообще умудрялись за ними следить? Теперь они просто разбросаны повсюду.$B$BУ меня уйдут недели, чтобы разобрать их обратно!', 24330),
(122068, 'ruRU', '', 'Прошу прощения. Эти приступы головокружения иногда настигают меня врасплох. Начались вскоре после нашего прибытия.', 24330),
(122071, 'ruRU', '', 'Скажи слово, и я раскрою скрытую угрозу!', 24330),
(122072, 'ruRU', '', 'Клянусь Светом... что это может значить?', 24330),
(122073, 'ruRU', '', 'Туралион и Аллерия... не могу поверить, что они были живы все эти годы...', 24330),
(122076, 'ruRU', '', 'Я слышал много об этих двух героях. У меня мало сомнений, что их весть имеет первостепенную важность.', 24330),
(122084, 'ruRU', '', 'У меня гораздо больше убийств, чем у тебя, Натанос. Ты теряешь хватку!', 24330),
(122087, 'ruRU', '', 'Похоже, ты чемпион по оправданиям!', 24330),
(122090, 'ruRU', '', 'Надеюсь, ты сможешь сохранить контроль над своими... способностями... в этом священном месте, "охотник на демонов". Мы будем наблюдать за тобой.', 24330),
(122092, 'ruRU', '', 'Охотник на демонов! Отлично, ты именно то, что мне нужно.', 24330),
(122097, 'ruRU', '', 'Ты не врал, Элиас. Охотники на демонов на свободе. Будь осторожен — с такими глазами $n видит всё.', 24330),
(122103, 'ruRU', '', 'Добро пожаловать, чужак.$b$bТвой народ нечасто забирается так высоко в горы, но тебе всё равно здесь рады.', 24330),
(122104, 'ruRU', '', 'Атаки дрогбаров оставили моей семье немногое, но то, что у нас есть — твоё, герой.', 24330),
(122113, 'ruRU', '', 'Даже самому преданному ремесленнику нужен отдых время от времени. Возьми спальную шкуру и отдохни в безопасности у моего очага.', 24330),
(122114, 'ruRU', '', 'Терпи достойно, $n. Мы будем готовы, когда тебе понадобимся.', 24330),
(122118, 'ruRU', '', 'Ох, привет, милашка. Нужно что-нибудь, или хочешь, чтобы я кого-то послала за чем-то для тебя.\n\nИли, знаешь, если просто хочешь поговорить, Никки здесь для тебя.', 24330),
(122171, 'ruRU', '', 'Помогите... прошу. Мои мысли... замедляются.', 24330),
(122180, 'ruRU', '', 'Я стала жрицей, чтобы помогать другим, но в последнее время задумываюсь, могу ли я сделать больше.', 24330),
(122189, 'ruRU', '', 'Мы готовы начать.', 24330),
(122191, 'ruRU', '', 'Вантир посчитал, что здесь нам будет безопаснее. После того, что случилось с моей дорогой Корин, я склонна согласиться.\n\nЭто тяжёлая жизнь, что ведут Иссохшие, но мы выстоим.\n\nЕщё раз благодарю за спасение моей дочери.', 24330),
(122202, 'ruRU', '', 'Здесь, в присутствии вечных защитников, я приношу эту священную клятву:', 24330),
(122204, 'ruRU', '', 'Я вверяю свою жизнь Ордену Серебряной Руки,', 24330),
(122205, 'ruRU', '', 'И присоединяюсь к своим братьям и сёстрам в смиренном служении.', 24330),
(122206, 'ruRU', '', 'С этой клятвой я перерождаюсь,', 24330),
(122207, 'ruRU', '', 'Воином Света.', 24330),
(122208, 'ruRU', '', 'Щит человечества, рука преданности и меч воздаяния.', 24330),
(122209, 'ruRU', '', 'Защищать слабых, поддерживать справедливость и идти праведным путём.', 24330),
(122210, 'ruRU', '', 'Это место в полном беспорядке!', 24330),
(122211, 'ruRU', '', 'Почти всё учтено! Кто бы мог подумать, что переезд Даларана вызовет столько проблем? Ещё один загон, птицы, и всё вернётся в норму!$B$B<Оглядывает комнату>.$B$BЗа исключением того бедняги в аквариуме. Надеюсь, это скоро решат.', 24330),
(122213, 'ruRU', '', 'Ох, не обращай на него внимания. Он весьма забывчив. Все выдержанные товары были хорошо упакованы ещё перед отъездом.$B$BОбязательно заходи к нам, когда лавка снова заработает! Уверен, мы достигнем конечного пункта назначения достаточно скоро!', 24330),
(122214, 'ruRU', '', 'Довольно много людей заходило в поисках облегчения от побочных эффектов.$B$BЕсли бы я только мог найти те старые рецепты... я знаю, они где-то здесь!', 24330),
(122238, 'ruRU', '', 'Что тебе нужно?', 24330),
(122243, 'ruRU', '', 'Да?', 24330),
(122246, 'ruRU', '', 'Пора?', 24330),
(122251, 'ruRU', '', 'Пусть Свет благословит тебя.', 24330),
(122261, 'ruRU', '', 'Прости, $n, но нас попросили пока не брать новых учеников. Уверен, когда мы достигнем конечного пункта назначения, всё вернётся в норму.', 24330),
(122263, 'ruRU', '', 'Добро пожаловать в "Корявую Ветвь", $n.', 24330),
(122288, 'ruRU', '', 'Как они могли поверить лжи Глашатая? Здесь замешана тёмная магия — запомни мои слова.\n\nПрошу, если ты можешь сделать что-нибудь, чтобы остановить это, сделай это сейчас же. Столько невинных жизней потеряно...', 24330),
(122289, 'ruRU', '', 'Оруженосцев обычно не так быстро обучают, но для тебя я ускорил этот заказ.', 24330),
(122292, 'ruRU', '', 'Добро пожаловать, $n. Пусть небесные хранители присматривают за тобой.', 24330);
